data.query:
query Query($where: WorkOrderWhereInput, $orderBy: [WorkOrderOrderByInput!], $first: Int, $after: String) {
  wo:workOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        workOrderStatusId
        productStrategy{
          id active validated
          strategyProcesses { edges{node{
            id
          }}}
        }
        dist:workOrderDistributions {
          edges {
            node {
              id
              calendarEventId
              productionHistories {
                total
              }
              distributionGroup{id workcenterId}
            }
          }
        }

        proc:workOrderProcesses {
          edges {
            node {
              id
              sourceInventoryTransactions{total}
              destinationInventoryTransactions{total}
              asset:workOrderProcessAssets{edges{node{id}}}
              bom:workOrderProcessBoms {
                edges {
                  node {
                    id
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

query Query($where: WorkOrderProcessWhereInput, $orderBy: [WorkOrderProcessOrderByInput!], $first: Int, $after: String) {
  wop:workOrderProcess(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        workOrderId
        workOrderProcessDistributions {

          edges {
            node {
              id

              calendarEventId
              distributionGroup{
                id workcenterId calendarEventId
              }
            }
          }
        }
      }
    }
  }
}

